class Solution {
    public double[] convertTemperature(double celsius) {
        double[] scales = {1.0, 1.80};
        double[] offsets = {273.15, 32.00};
        double[] answer = new double[2];
        for (int i = 0; i < 2; i++) {
            answer[i] = scales[i] * celsius + offsets[i];
        }
        return answer;
    }
}

class Solution {
    private static final double KELVIN_OFFSET = 273.15;
    private static final double FAHRENHEIT_SCALE = 1.80;
    private static final double FAHRENHEIT_OFFSET = 32.00;

    public double[] convertTemperature(double celsius) {
        return new double[]{toKelvin(celsius), toFahrenheit(celsius)};
    }

    private double toKelvin(double celsius) {
        return celsius + KELVIN_OFFSET;
    }

    private double toFahrenheit(double celsius) {
        return celsius * FAHRENHEIT_SCALE + FAHRENHEIT_OFFSET;
    }
}
